import{_ as l,a0 as d,w as p,s as o,ao as r,I as n,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 上永久掛載一個 Windows 共享 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上永久掛載一個 Windows 共享 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上永久掛載一個 Windows 共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上永久掛載一個 Windows 共享 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160624 How to permanently mount a Windows share on Linux","title":"如何在 Linux 上永久掛載一個 Windows 共享","tag":"201607","desc":""},"relativePath":"201607/20160624 How to permanently mount a Windows share on Linux.md","filePath":"[post].md"}'),h={name:"201607/20160624 How to permanently mount a Windows share on Linux.md"};function u(g,s,b,c,k,f){const e=d("Link");return p(),o("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-上永久掛載一個-windows-共享" tabindex="-1">如何在 Linux 上永久掛載一個 Windows 共享 <a class="header-anchor" href="#如何在-linux-上永久掛載一個-windows-共享" aria-label="Permalink to “如何在 Linux 上永久掛載一個 Windows 共享”">​</a></h1><blockquote><p>如果你已經厭倦了每次重啓 Linux 就得重新掛載 Windows 共享，讀讀這個讓共享永久掛載的簡單方法。</p></blockquote><p><img src="http://tr2.cbsistatic.com/hub/i/2016/06/02/e965310b-b38d-43e6-9eac-ea520992138b/68fd9ec5d6731cc405bdd27f2f42848d/linuxadminhero.jpg" alt=""></p><p><em>圖片： Jack Wallen</em></p><p>在 Linux 上和一個 Windows 網絡進行交互從來就不是件輕鬆的事情。想想多少企業正在採用 Linux，需要在這兩個平台上彼此協作。幸運的是，有了一些工具的幫助，你可以輕鬆地將 Windows 網絡驅動器映射到一台 Linux 機器上，甚至可以確保在重啓 Linux 機器之後共享還在。</p><h3 id="在我們開始之前" tabindex="-1">在我們開始之前 <a class="header-anchor" href="#在我們開始之前" aria-label="Permalink to “在我們開始之前”">​</a></h3><p>要實現這個，你需要用到命令列。過程十分簡單，但你需要編輯 /etc/fstab 文件，所以小心操作。還有，我假設你已經讓 Samba 正常工作了，可以手動從 Windows 網絡掛載共享到你的 Linux 機器，還知道這個共享的主機 IP 地址。</p><p>準備好了嗎？那就開始吧。</p><h3 id="創建你的掛載點" tabindex="-1">創建你的掛載點 <a class="header-anchor" href="#創建你的掛載點" aria-label="Permalink to “創建你的掛載點”">​</a></h3><p>我們要做的第一件事是創建一個文件夾，他將作為共享的掛載點。為了簡單起見，我們將這個文件夾命名為 share，放在 /media 之下。打開你的終端執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /media/share</span></span></code></pre></div><h3 id="安裝一些軟件" tabindex="-1">安裝一些軟件 <a class="header-anchor" href="#安裝一些軟件" aria-label="Permalink to “安裝一些軟件”">​</a></h3><p>現在我們得安裝允許跨平台文件共享的系統；這個系統是 cifs-utils。在終端窗口輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install cifs-utils</span></span></code></pre></div><p>這個命令同時還會安裝 cifs-utils 所有的依賴。</p><p>安裝完成之後，打開文件 /etc/nsswitch.conf 並找到這一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hosts: files mdns4_minimal [NOTFOUND=return] dns</span></span></code></pre></div><p>編輯這一行，讓它看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hosts: files mdns4_minimal [NOTFOUND=return] wins dns</span></span></code></pre></div><p>現在你需要安裝 windbind 讓你的 Linux 機器可以在 DHCP 網絡中解析 Windows 機器名。在終端裏執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install libnss-windbind windbind</span></span></code></pre></div><p>用這個命令重啓網絡服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service networking restart</span></span></code></pre></div><h3 id="掛載網絡驅動器" tabindex="-1">掛載網絡驅動器 <a class="header-anchor" href="#掛載網絡驅動器" aria-label="Permalink to “掛載網絡驅動器”">​</a></h3><p>現在我們要映射網絡驅動器。這裏我們必須編輯 /etc/fstab 文件。在你做第一次編輯之前，用這個命令備份以下這個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/fstab /etc/fstab.old</span></span></code></pre></div><p>如果你需要恢復這個文件，執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mv /etc/fstab.old /etc/fstab</span></span></code></pre></div><p>在你的主目錄創建一個認證信息文件 .smbcredentials。在這個文件裏添加你的用户名和密碼，就像這樣（USER 和 PASSWORD 替換為實際的用户名和密碼）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>username=USER</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password=PASSWORD</span></span></code></pre></div><p>你需要知道掛載這個驅動器的用户的組 ID（GID）和用户 ID（UID）。執行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>id USER</span></span></code></pre></div><p>USER 是你的實際用户名，你應該會看到類似這樣的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uid=1000(USER) gid=1000(GROUP)</span></span></code></pre></div><p>USER 是實際的用户名，GROUP 是組名。在（USER）和（GROUP）之前的數字將會被用在 /etc/fstab 文件之中。</p><p>是時候編輯 /etc/fstab 文件了。在你的編輯器中打開那個文件並添加下面這行到文件末尾（替換以下全大寫字段以及遠程機器的 IP 地址）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>//192.168.1.10/SHARE /media/share cifs credentials=/home/USER/.smbcredentials,iocharset=uft8,gid=GID,udi=UID,file_mode=0777,dir_mode=0777 0 0</span></span></code></pre></div><p><strong>注意</strong>：上面這些內容應該在同一行上。</p><p>保存並關閉那個文件。執行 sudo mount -a 命令，共享將被掛載。檢查一下 /media/share，你應該能看到那個網絡共享上的文件和文件夾了。</p><h3 id="共享很簡單" tabindex="-1">共享很簡單 <a class="header-anchor" href="#共享很簡單" aria-label="Permalink to “共享很簡單”">​</a></h3><p>有了 cifs-utils 和 Samba，映射網絡共享在一台 Linux 機器上簡單得讓人難以置信。現在，你再也不用在每次機器啓動的時候手動重新掛載那些共享了。</p>`,41)),n("p",null,[s[1]||(s[1]=i("更多網絡提示和技巧，訂閲我們的 Data Center 消息吧。 ",-1)),a(e,{href:"https://secure.techrepublic.com/user/login/?regSource=newsletter-button&position=newsletter-button&appId=true&redirectUrl=http%3A%2F%2Fwww.techrepublic.com%2Farticle%2Fhow-to-permanently-mount-a-windows-share-on-linux%2F&"},{default:t(()=>[...s[0]||(s[0]=[i("訂閲",-1)])]),_:1})]),s[16]||(s[16]=n("hr",null,null,-1)),n("p",null,[s[3]||(s[3]=i("via: ",-1)),a(e,{href:"http://www.techrepublic.com/article/how-to-permanently-mount-a-windows-share-on-linux/"},{default:t(()=>[...s[2]||(s[2]=[i("http://www.techrepublic.com/article/how-to-permanently-mount-a-windows-share-on-linux/",-1)])]),_:1})]),n("p",null,[s[7]||(s[7]=i("作者：",-1)),a(e,{href:"http://www.techrepublic.com/search/?a=jack+wallen"},{default:t(()=>[...s[4]||(s[4]=[i("Jack Wallen",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),a(e,{href:"https://github.com/alim0x"},{default:t(()=>[...s[5]||(s[5]=[i("alim0x",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[6]||(s[6]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const y=l(h,[["render",u]]);export{x as __pageData,y as default};
